{
  "name": "get_device_config",
  "confidence": "medium",
  "docstring": "Selects a 16-byte device configuration table entry from a control-register-derived index, copies selected fields into a global and an 8-byte output buffer, and returns the table entry pointer.",
  "subsystem": "hal",
  "var_renames": {
    "v0": "out_cfg",
    "v1": "config_index",
    "result": "cfg_entry",
    "v3": "cfg_word"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "16-bit config table field copied to global pointed to by off_1005E4"
    },
    {
      "offset": 6,
      "meaning": "16-bit config table field truncated and stored into out_cfg byte offset 1"
    },
    {
      "offset": 0,
      "meaning": "output status/config byte set to 0xff"
    },
    {
      "offset": 1,
      "meaning": "output status/config byte copied from selected table entry"
    }
  ]
}
